export function MemorialDetail(i){return`<div class="memorial-detail" data-id="${i.id}">\n    <div class="memorial-detail-header" style="border-top-color: ${i.color}">\n      <div class="memorial-detail-image">\n        <img src="${i.image}" alt="${i.name}" />\n      </div>\n      <div class="memorial-detail-info">\n        <span class="memorial-detail-year" style="background: ${i.color}">${i.built}</span>\n        <h2 class="memorial-detail-name">${i.name}</h2>\n        <p class="memorial-detail-location">${i.city}, ${i.state}</p>\n        <p class="memorial-detail-architect"><strong>Architect:</strong> ${i.architect}</p>\n        <p class="memorial-detail-style"><strong>Style:</strong> ${i.architecturalStyle}</p>\n      </div>\n    </div>\n    <div class="memorial-detail-body">\n      <div class="memorial-detail-section">\n        <h3>Significance</h3>\n        <p>${i.significance}</p>\n      </div>\n      <div class="memorial-detail-section">\n        <h3>History</h3>\n        <p>${i.history}</p>\n      </div>\n      <div class="memorial-detail-visiting">\n        <div class="visiting-info">\n          <span class="visiting-label">Visiting Hours</span>\n          <span class="visiting-value">${i.visitingHours}</span>\n        </div>\n        <div class="visiting-info">\n          <span class="visiting-label">Status</span>\n          <span class="visiting-value">${i.status}</span>\n        </div>\n      </div>\n    </div>\n  </div>`}